  (SELECT id FROM livro WHERE isbn = '9788576570891' ORDER BY id LIMIT 1),
  1,
  59.90
WHERE
  (SELECT id FROM pedido WHERE data_pedido = '2026-06-15 20:56:14' ORDER BY id LIMIT 1) IS NOT NULL
  AND (SELECT id FROM livro WHERE isbn = '9788576570891' ORDER BY id LIMIT 1) IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM item_pedido 
    WHERE pedido_id = (SELECT id FROM pedido WHERE data_pedido = '2026-06-15 20:56:14' ORDER BY id LIMIT 1)
      AND livro_id = (SELECT id FROM livro WHERE isbn = '9788576570891' ORDER BY id LIMIT 1)
  );
